.sj-header{height:92px;padding:0 clamp(22px,4.5vw,72px);border-bottom:1px solid var(--sj-line);background:rgba(251,250,246,.95)}.sj-logo{font-family:Georgia,serif;font-size:25px;font-weight:700;letter-spacing:.08em}.sj-logo span{color:var(--sj-gold)}.sj-header nav{gap:38px;margin-left:auto;margin-right:35px}.sj-header nav a{font-size:12px;letter-spacing:.08em;text-transform:uppercase}.sj-header nav a:hover{color:var(--sj-gold)}.sj-search{width:42px;height:42px;border:1px solid var(--sj-line);border-radius:50%}.sj-mobile-menu{display:none;position:relative}.sj-mobile-menu summary{list-style:none}.sj-mobile-menu summary::-webkit-details-marker{display:none}.sj-mobile-menu>div{position:absolute;right:0;top:42px;z-index:20;width:240px;padding:10px;border:1px solid var(--sj-line);background:var(--sj-paper);box-shadow:0 16px 40px rgba(33,31,28,.12)}.sj-mobile-menu a{padding:13px 14px;border-bottom:1px solid var(--sj-line);font-size:12px;text-transform:uppercase}
.sj-hero{grid-template-columns:39% 61%;min-height:670px}.sj-hero-copy{padding:80px clamp(35px,7vw,120px) 80px clamp(25px,5vw,80px);background:#f4efe6}.sj-category{color:var(--sj-gold);font-size:10px;font-weight:700;letter-spacing:.16em}.sj-hero h1{margin:22px 0 30px;font-size:clamp(55px,5.7vw,96px);line-height:.93;letter-spacing:-.055em}.sj-hero-copy>p:nth-of-type(2){max-width:430px;color:#716b62}.sj-button{width:230px;min-height:54px;margin-top:35px;padding:0 20px;background:var(--sj-ink);color:#fff;font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}.sj-button:hover{background:var(--sj-gold)}.sj-button.is-light{border:1px solid var(--sj-ink);background:transparent;color:var(--sj-ink)}.sj-button.is-light:hover{background:var(--sj-ink);color:#fff}.sj-hero-image img{transition:transform 1.1s cubic-bezier(.16,1,.3,1)}.sj-hero-image:hover img{transform:scale(1.025)}.sj-hero-image figcaption{right:0;bottom:0;left:0;padding:18px 25px;background:rgba(22,20,18,.88);color:#fff;font-size:10px;letter-spacing:.1em;text-transform:uppercase}
