.sj-latest{border-top:1px solid var(--sj-line)}.sj-latest-head .sj-section-title h2{font-size:clamp(60px,8vw,110px)}.sj-latest-layout{grid-template-columns:1fr 330px;gap:70px;margin-top:55px}.sj-latest-grid{grid-template-columns:repeat(2,1fr);gap:55px 32px}.sj-latest-grid .sj-story-image{height:310px}.sj-latest-layout>aside{padding-left:30px;border-left:1px solid var(--sj-line)}.sj-latest-layout>aside>h3{margin-bottom:12px;color:var(--sj-gold);font-size:27px}.sj-latest-layout>aside>article{grid-template-columns:28px 80px 1fr;gap:12px;padding:18px 0;border-top:1px solid var(--sj-line)}.sj-latest-layout>aside>article>span{color:#aaa;font-family:Georgia,serif}.sj-latest-layout>aside>article img{height:68px}.sj-latest-layout>aside h4{margin-top:5px;font-size:15px;line-height:1.2}.sj-side-note{margin-top:35px;padding:28px;background:#f1eadf}.sj-side-note p{margin:14px 0;font-family:Georgia,serif;font-size:22px;line-height:1.15}.sj-side-note a{font-size:10px;font-weight:700;text-transform:uppercase}
