.sj-footer{padding:75px clamp(25px,6vw,95px) 25px;background:#181714;color:#fff}.sj-footer-main{grid-template-columns:1.4fr repeat(3,1fr);gap:60px}.sj-footer-main>div{display:flex;flex-direction:column;align-items:flex-start;gap:10px}.sj-footer-main>div:first-child p{max-width:250px;color:#98948d}.sj-footer-main strong{margin-bottom:7px;color:var(--sj-gold);font-size:10px;letter-spacing:.13em;text-transform:uppercase}.sj-footer-main a:not(.sj-logo),.sj-footer-main span{gap:8px;color:#bbb6ae;font-size:12px}.sj-footer-main a:hover{color:#fff}.sj-footer-bottom{margin-top:65px;padding-top:22px;border-top:1px solid #3c3934;color:#8e8981;font-size:10px}.sj-footer-bottom a{gap:7px;color:#fff}
@keyframes sj-pulse{50%{opacity:.3;transform:scale(.65)}}@keyframes sj-rise{from{opacity:0;transform:translateY(20px)}to{opacity:1;transform:none}}@media(prefers-reduced-motion:no-preference){.serein-journal .motion-safe\:co-animate-pulse{animation:sj-pulse 1.8s ease-in-out infinite}.sj-feature-layout,.sj-essay article,.sj-three-up,.sj-essential>.sj-story-card,.sj-latest-layout{animation:sj-rise .8s both;animation-timeline:view();animation-range:entry 10% cover 28%}}@media(prefers-reduced-motion:reduce){.serein-journal *,.serein-journal *::before,.serein-journal *::after{animation:none!important;scroll-behavior:auto!important;transition-duration:.01ms!important}}
